import{_ as d,o as r,c as e,af as a}from"./chunks/framework.zl0XNxp1.js";const p=JSON.parse('{"title":"我的健身记录💪","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/11_my_exercise.md","filePath":"2_articles/11_my_exercise.md","lastUpdatedText":"2026-06-24 20:31:51"}'),h={name:"2_articles/11_my_exercise.md"};function o(g,t,c,n,s,k){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="我的健身记录💪" tabindex="-1">我的健身记录💪 <a class="header-anchor" href="#我的健身记录💪" aria-label="Permalink to &quot;我的健身记录💪&quot;">​</a></h1><p><code>24年4月份</code>第一次接触健身，信誓旦旦的办了四个月的卡，啥也不懂就买了增肌粉，抱着练一休一，甚至练一休半月的惰性，给自己找了无数忙的理由，最后断断续续连一个月都没练下。</p><p><code>24年底</code>在上海实习的时候，感受到互联网算法庞大的压力，突然觉得自己应该要有一个好的身体去应对未来(<strong>以及女朋友答应25年底的时候见双方父母</strong>)，下定决心要做个改变，实习结束回到学校后，从2025年3月1日开始，踏上了我一个人的健身之路，此博客记录开始于2025年5月21日，这两个多月里已经将健身当成了习惯，每天下午五点，我都会像NPC一样出现在上海北路......</p><p><code>25年6月</code>本科毕业回老家后，和我的三个好兄弟组成<code>健身房龙级灾害——精灵团</code>,继续我们的健身之路......</p><p><code>25年9月</code>研究生开学后来到天津，和女朋友找到一个距离两个校区差不多远的健身房，带女朋友也一起健身🥰</p><p><code>25年12月</code>因为平时太忙，没办法每天都坐一小时的地铁去和女朋友一起健身，所以又跟<a href="https://xiangyuli-bio.github.io/" target="_blank" rel="noreferrer">宇</a>、<a href="https://weipengchao.top/" target="_blank" rel="noreferrer">超</a>组成新的<code>健身房龙级灾害</code>，每天过上<code>硕士男屌丝</code>的生活～</p><p><code>26年4月</code>新的学期开始带领整个实验室一起变成体育生!</p><h2 id="记录" tabindex="-1">记录 <a class="header-anchor" href="#记录" aria-label="Permalink to &quot;记录&quot;">​</a></h2><p><strong>1/4：胸肌 + 三头肌</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*8)</th><th>现在做组重量(4*8)</th><th>PR</th></tr></thead><tbody><tr><td>平板卧推</td><td>4</td><td>8</td><td>25kg</td><td>65kg</td><td>暂未尝试</td></tr><tr><td>上斜哑铃卧推</td><td>4</td><td>8</td><td>7.5kg</td><td>27.5kg</td><td>暂未尝试</td></tr><tr><td>双杠臂屈伸</td><td>4</td><td>8</td><td>辅助</td><td>自重</td><td>暂未尝试</td></tr><tr><td>绳索下压</td><td>4</td><td>8</td><td>龙门架一片(没看过多重)</td><td>7片</td><td>暂未尝试</td></tr><tr><td>蝴蝶机夹胸</td><td>4</td><td>8</td><td>20kg</td><td>50kg</td><td>暂未尝试</td></tr></tbody></table><p><strong>2/4: 背 + 二头肌</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*8)</th><th>现在做组重量(4*8)</th><th>PR</th></tr></thead><tbody><tr><td>高位下拉</td><td>4</td><td>8</td><td>27kg</td><td>61kg</td><td>暂未尝试</td></tr><tr><td>俯身器械划船</td><td>4</td><td>8</td><td>10kg</td><td>35kg</td><td>暂未尝试</td></tr><tr><td>大剪刀</td><td>4</td><td>8</td><td>35kg</td><td>35kg</td><td>暂未尝试</td></tr><tr><td>坐姿划船</td><td>4</td><td>8</td><td>20kg</td><td>61kg</td><td>暂未尝试</td></tr><tr><td>辅助引体</td><td>4</td><td>8</td><td>44kg</td><td>自重</td><td>暂未尝试</td></tr><tr><td>杠铃弯举</td><td>4</td><td>8</td><td>10kg</td><td>25kg</td><td>暂未尝试</td></tr><tr><td>哑铃交替弯举</td><td>4</td><td>8</td><td>5kg</td><td>12.5kg</td><td>暂未尝试</td></tr></tbody></table><p><strong>3/4：肩 + 核心</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*8)</th><th>现在做组重量(4*8)</th><th>PR</th></tr></thead><tbody><tr><td>坐姿哑铃推肩</td><td>4</td><td>8</td><td>7.5kg</td><td>25kg</td><td>暂未尝试</td></tr><tr><td>哑铃飞鸟</td><td>4(递减力竭组)</td><td>8</td><td>5kg</td><td>10kg</td><td>暂未尝试</td></tr><tr><td>绳索面拉</td><td>4</td><td>8</td><td>25kg</td><td>44kg</td><td>暂未尝试</td></tr><tr><td>龙门架卷腹</td><td>5</td><td>20</td><td>50kg</td><td>60kg</td><td></td></tr><tr><td>悬垂举腿</td><td>5</td><td>15</td><td>自重</td><td>自重</td><td></td></tr></tbody></table><p><strong>4/4：腿</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>组数</th><th>每组次数</th><th>初始做组重量(4*8)</th><th>现在做组重量(4*8)</th><th>PR</th></tr></thead><tbody><tr><td>自由深蹲</td><td>4</td><td>8</td><td>40kg</td><td>80kg</td><td>100kg</td></tr><tr><td>倒蹬</td><td>4</td><td>8</td><td>70kg</td><td>130kg</td><td>暂未尝试</td></tr><tr><td>哈克深蹲</td><td>4</td><td>8</td><td>90kg</td><td>130kg</td><td>暂未尝试</td></tr></tbody></table><hr>',17)])])}const _=d(h,[["render",o]]);export{p as __pageData,_ as default};
